-- Seed script for Mudra: 50 instruments, trading calendar holidays, and initial closing prices

-- 1. Seed 50 NSE Instruments
ON CONFLICT (exchange, symbol) DO UPDATE SET is_active = true;

-- 2. Seed Trading Calendar (Holidays)
ON CONFLICT (trade_date) DO NOTHING;

-- 3. Seed Recent Closing Prices
ON CONFLICT (instrument_id, trade_date) DO NOTHING;
